fn need(ok:bool,msg:&str){if !ok{panic!("{}",msg)}}
fn parse_i(x:&str)->i128{x.parse().unwrap()}
fn parse_u(x:&str)->u64{x.parse().unwrap()}
fn unhex(x:&str)->Row{need(x.len()==48,"row hex length");let mut a=[0u8;24];for i in 0..24{a[i]=u8::from_str_radix(&x[2*i..2*i+2],16).unwrap()}Row(a)}
fn hx(r:&Row)->String{r.0.iter().map(|x|format!("{:02x}",x)).collect()}

fn family_total(f:&str)->u64{match f{"k14"|"k15"|"direct17"|"k14fast"=>485,"k16"=>24_097_095,"hidden18"=>158_439_965,"hidden_pair"=>101_545_723,_=>panic!("bad family")}}
fn path(g:&str)->&'static[usize]{match g{
 "source_D14_R2_2_2_4"=>&[2,2,2,4],"source_D14_R2_4_4"=>&[2,4,4],
 "source_D14_R3_3_4"=>&[3,3,4],"source_D14_R4_2_4"=>&[4,2,4],
 "source_D15_R2_3_4"=>&[2,3,4],"source_D15_R3_2_4"=>&[3,2,4],
 "source_D16_R2_2_4"=>&[2,2,4],"source_D16_R4_4"=>&[4,4],
 "source_D17_R3_4"=>&[3,4],"source_D18_R2_4"=>&[2,4],_=>panic!("bad group")}}
fn lineage(g:&str)->&'static str{match g{
 "source_D14_R2_2_2_4"=>"D14:222|R:2-2-2-4",
 "source_D14_R2_4_4"=>"D14:222|R:2-4-4",
 "source_D14_R3_3_4"=>"D14:222|R:3-3-4",
 "source_D14_R4_2_4"=>"D14:222|R:4-2-4",
 "source_D15_R2_3_4"=>"D15:223|R:2-3-4+D15:232|R:2-3-4+D15:322|R:2-3-4",
 "source_D15_R3_2_4"=>"D15:223|R:3-2-4+D15:232|R:3-2-4+D15:322|R:3-2-4",
 "source_D16_R2_2_4"=>"D16:224|R:2-2-4+D16:233|R:2-2-4+D16:242|R:2-2-4+D16:323|R:2-2-4+D16:332|R:2-2-4+D16:422|R:2-2-4",
 "source_D16_R4_4"=>"D16:224|R:4-4+D16:233|R:4-4+D16:242|R:4-4+D16:323|R:4-4+D16:332|R:4-4+D16:422|R:4-4",
 "source_D17_R3_4"=>"D17:234|R:3-4+D17:243|R:3-4+D17:324|R:3-4+D17:333|R:3-4+D17:342|R:3-4+D17:423|R:3-4+D17:432|R:3-4",
 "source_D18_R2_4"=>"D18:244|R:2-4+D18:334|R:2-4+D18:343|R:2-4+D18:424|R:2-4+D18:433|R:2-4+D18:442|R:2-4",
 _=>panic!("bad group")}}

fn formula_head_at(e:&E,family:&str,gid:&str,ri:usize,ordinal:u64)->Option<(Row,i128)>{
 let r=&e.records[ri];let positive=r.size as i128*r.coefficient as i128;let mut n=0u64;
 macro_rules! emit{($row:expr)=>{{let z=$row;if n==ordinal{return Some((z,-positive))}n+=1;}}}
 if family=="k14"{for a in &e.factor[0][0]{for b in &e.factor[1][0]{for c in &e.factor[2][0]{emit!(make(r,a,b,c));}}}}
 else if family=="k15"{for packet in 0..3{let o:Vec<_>=(0..3).filter(|&x|x!=packet).collect();for a in &e.factor[o[0]][0]{for b in &e.factor[o[1]][0]{for c in &e.factor[packet][1]{emit!(match packet{0=>make(r,c,a,b),1=>make(r,a,c,b),_=>make(r,a,b,c)});}}}}}
 else if gid=="source_D17_R3_4"{
  let specs=[(0usize,1usize,2usize),(0,2,1),(1,0,2),(1,2,0),(2,0,1),(2,1,0)];
  for &(d2,d3,d4) in &specs{for a in &e.factor[d2][0]{for b in &e.factor[d3][1]{for c in &e.factor[d4][2]{let mut f:[Option<&[u8;4]>;3]=[None,None,None];f[d2]=Some(a);f[d3]=Some(b);f[d4]=Some(c);emit!(make(r,f[0].unwrap(),f[1].unwrap(),f[2].unwrap()));}}}}
  for a in &e.factor[0][1]{for b in &e.factor[1][1]{for c in &e.factor[2][1]{emit!(make(r,a,b,c));}}}
 }else if gid=="source_D18_R2_4"{
  for low in 0..3{let o:Vec<_>=(0..3).filter(|&x|x!=low).collect();for a in &e.factor[low][0]{for b in &e.factor[o[0]][2]{for c in &e.factor[o[1]][2]{emit!(match low{0=>make(r,a,b,c),1=>make(r,b,a,c),_=>make(r,b,c,a)});}}}}
  for high in 0..3{let o:Vec<_>=(0..3).filter(|&x|x!=high).collect();for a in &e.factor[o[0]][1]{for b in &e.factor[o[1]][1]{for c in &e.factor[high][2]{emit!(match high{0=>make(r,c,a,b),1=>make(r,a,c,b),_=>make(r,a,b,c)});}}}}
 }else{panic!("formula family/group mismatch")}
 None
}

fn k16_head(index:u64)->(Row,i128){let mut f=File::open(K16_INPUT).unwrap();f.seek(SeekFrom::Start(16+32*index)).unwrap();let mut b=[0u8;32];f.read_exact(&mut b).unwrap();let mut r=[0u8;24];r.copy_from_slice(&b[..24]);(Row(r),i64::from_le_bytes(b[24..].try_into().unwrap())as i128)}

fn terminal_charge(row:&Row,s:[u8;12],p:usize,e:&E)->i64{let mut cache=HashMap::new();let z=resp(row,s,p,4,e,&mut cache);need(z.0==z.1,"full/irreducible charge mismatch");need(z.2==60&&z.3==60,"terminal response count not 60");for t in &e.tails[p][2]{need(avail(child_sig(s,p,t,e),e).is_empty(),"nonterminal K24 tail")}z.0}

fn replay_physical(fields:&[&str],family:&str,e:&E){
 need(fields.len()==12,"physical sample arity");let index=parse_u(fields[1]);need(index<family_total(family),"source index range");let gid=fields[2];need(fields[3]==lineage(gid),"lineage mismatch");let ordinal=parse_u(fields[4]);let head=unhex(fields[5]);let source=parse_i(fields[6]);
 let expected=if family=="k16"{need(ordinal==0,"K16 ordinal must be zero");k16_head(index)}else{formula_head_at(e,family,gid,index as usize,ordinal).expect("head ordinal out of range")};need(head==expected.0,"source head row mismatch");need(source==expected.1,"source coefficient mismatch");
 let route=path(gid);need(route.len()>=2&&route.len()<=3,"physical path length");let steps:Vec<_>=fields[11].split(';').collect();need(steps.len()==route.len(),"literal step count mismatch");let mut row=head;let mut s=sig(&row,e);let mut ps=if family=="k14"{valid(s,e)}else{avail(s,e)};let mut den=1usize;
 for (depth,text) in steps.iter().enumerate(){let q:Vec<_>=text.split(':').collect();need(q.len()==4,"bad literal step");let p:usize=q[0].parse().unwrap();need(ps.contains(&p),"selected pivot unavailable");need(q[2].parse::<usize>().unwrap()==route[depth],"step degree/path mismatch");den*=ps.len();
  if depth+1<steps.len(){let t:usize=q[1].parse().unwrap();need(t<e.tails[p][route[depth]-2].len(),"tail index range");let child=replace(&row,&e.anchors[p],&e.tails[p][route[depth]-2][t]);need(child==unhex(q[3]),"literal child row mismatch");row=child;s=sig(&row,e);ps=avail(s,e);need(!ps.is_empty(),"stored intermediate is not pivotable");}
  else{need(q[1]=="-","final step must use aggregate marker");need(row==unhex(q[3]),"preterminal row mismatch");let charge=terminal_charge(&row,s,p,e);need(charge==fields[9].parse().unwrap(),"terminal K4 charge mismatch");}
 }
 need(den as i128==parse_i(fields[7]),"denominator product mismatch");need(U%den as i128==0,"denominator outside U");let sign=if route.len()%2==0{1}else{-1};let unit=source*sign*U/den as i128;need(unit==parse_i(fields[8]),"unit/sign mismatch");need(unit*parse_i(fields[9])==parse_i(fields[10]),"contribution mismatch");
}

