fn h18(index:u64)->H18{let mut f=File::open(H18_INPUT).unwrap();f.seek(SeekFrom::Start(80+80*index)).unwrap();let mut b=[0u8;80];f.read_exact(&mut b).unwrap();let mut r=[0u8;24];r.copy_from_slice(&b[..24]);H18{row:Row(r),weight:i128::from_le_bytes(b[24..40].try_into().unwrap()),orbit:u16::from_le_bytes(b[74..76].try_into().unwrap()),stabilizer:u16::from_le_bytes(b[76..78].try_into().unwrap()),m2:b[79]}}
