fn replay_hidden(fields:&[&str],family:&str,e:&E){
 need(fields.len()==14,"hidden sample arity");let index=parse_u(fields[1]);need(index<family_total(family),"source index range");let gid=fields[2];need(fields[3]==lineage(gid),"lineage mismatch");let weight=parse_i(fields[4]);let m_prev:usize=fields[5].parse().unwrap();let m_final:usize=fields[6].parse().unwrap();let pre_p:usize=fields[7].parse().unwrap();let tail:usize=fields[8].parse().unwrap();let final_p:usize=fields[9].parse().unwrap();let row20=unhex(fields[13]);
 let (source_row,degree,expected_unit)=if family=="hidden18"{let x=h18(index);need(x.orbit as u32*x.stabilizer as u32==384,"H18 orbit identity");need(x.weight==weight,"H18 retained weight mismatch");let s=sig(&x.row,e);let ps=avail(s,e);need(ps.len()==m_prev&&ps.contains(&pre_p),"H18 first pivot/multiplicity mismatch");need(tail<12,"H18 K2 tail range");need(row20==replace(&x.row,&e.anchors[pre_p],&e.tails[pre_p][0][tail]),"H18 K20 row mismatch");(x.row,2,weight/(m_prev*m_final)as i128)}else{let x=pair(index);need(x.orbit as u32*x.stabilizer as u32==384,"pair orbit identity");need(x.weight==weight,"pair retained weight mismatch");let s=sig(&x.row,e);let ps=avail(s,e);need(ps.len()==m_prev&&x.pivot==pre_p&&ps.contains(&pre_p),"pair first pivot/multiplicity mismatch");need(tail<60,"pair K4 tail range");need(row20==replace(&x.row,&e.anchors[pre_p],&e.tails[pre_p][2][tail]),"pair K20 row mismatch");(x.row,4,-weight/m_final as i128)};
 let _=source_row;let _=degree;let s20=sig(&row20,e);let ps=avail(s20,e);need(ps.len()==m_final&&ps.contains(&final_p),"terminal pivot/multiplicity mismatch");need(weight%m_final as i128==0,"retained weight not divisible by final multiplicity");if family=="hidden18"{need(weight%(m_prev*m_final)as i128==0,"H18 retained weight not divisible by current product")}
 need(expected_unit==parse_i(fields[10]),"hidden unit/sign mismatch");let charge=terminal_charge(&row20,s20,final_p,e);need(charge==fields[11].parse().unwrap(),"hidden terminal charge mismatch");need(expected_unit*charge as i128==parse_i(fields[12]),"hidden contribution mismatch");
}

fn replay_hidden_decorated_fast(fields:&[&str],e:&E){
 need(fields.len()==14,"fast hidden-decorated sample arity");let index=parse_u(fields[0]);need(index<101_545_723,"fast hidden-decorated index range");let x=pair(index);need(x.row==unhex(fields[1]),"fast hidden-decorated source row seek mismatch");need(x.pivot==fields[2].parse::<usize>().unwrap(),"fast hidden-decorated p2 mismatch");need(x.weight==parse_i(fields[3]),"fast hidden-decorated retained weight mismatch");need(x.uses==parse_u(fields[4]),"fast hidden-decorated pair uses mismatch");need(x.orbit==fields[5].parse::<u16>().unwrap()&&x.stabilizer==fields[6].parse::<u16>().unwrap()&&x.orbit as u32*x.stabilizer as u32==384,"fast hidden-decorated orbit identity");let s16=sig(&x.row,e);let ps2=avail(s16,e);need(!ps2.is_empty()&&ps2.contains(&x.pivot),"fast hidden-decorated selected p2 unavailable");let m2=ps2.len();let mut first=0u64;let mut pivotable=0u64;let mut selected=0u64;let mut terminal=0u64;let mut terminal_weight=0i128;let mut charge=0i128;for t in &e.tails[x.pivot][2]{first+=1;let row20=replace(&x.row,&e.anchors[x.pivot],t);let s20=sig(&row20,e);let ps3=avail(s20,e);if ps3.is_empty(){continue}pivotable+=1;let m3=ps3.len();need(U%(m2*m3)as i128==0,"fast hidden-decorated denominator outside U");need(x.weight%m3 as i128==0,"fast hidden-decorated retained weight indivisible by m3");let w3=-x.weight/m3 as i128;for p3 in ps3{selected+=1;let q=terminal_charge(&row20,s20,p3,e);terminal+=60;terminal_weight+=60*w3;charge+=w3*q as i128}}need(first==60,"fast hidden-decorated first-tail count");need(first==parse_u(fields[7]),"fast hidden-decorated stored first children");need(pivotable==parse_u(fields[8]),"fast hidden-decorated stored pivotable intermediates");need(selected==parse_u(fields[9]),"fast hidden-decorated stored selected p3");need(terminal==parse_u(fields[10])&&terminal==60*selected,"fast hidden-decorated terminal occurrences");need(terminal_weight==parse_i(fields[11]),"fast hidden-decorated terminal weight");need(charge==parse_i(fields[12]),"fast hidden-decorated charge");need((selected>0)==(fields[13]=="1"),"fast hidden-decorated nonzero flag");
}

