 need(fields.len()==28,"fast K14 sample arity");let id=fields[0];need(id=="D14:222|R:3-3-4"||id=="D14:222|R:4-2-4","fast K14 lineage");let bin:usize=fields[1].parse().unwrap();let head:usize=fields[2].parse().unwrap();let ri:usize=fields[3].parse().unwrap();need(ri<485&&head/1728==ri,"fast K14 head/source index mismatch");need(bin==head*257/(485*1728),"fast K14 distributed bin mismatch");let local=head%1728;let(a,b,c)=(local/144,(local/12)%12,local%12);let r=&e.records[ri];let row14=make(r,&e.factor[0][0][a],&e.factor[1][0][b],&e.factor[2][0][c]);need(row14==unhex(fields[4]),"fast K14 source row mismatch");let source=r.size as i128*r.coefficient as i128;need(source==parse_i(fields[5]),"fast K14 source mass mismatch");
 let(first,second)=if id.ends_with("3-3-4"){(3usize,3usize)}else{(4usize,2usize)};let p1:usize=fields[15].parse().unwrap();let t1:usize=fields[16].parse().unwrap();let p2:usize=fields[17].parse().unwrap();let t2:usize=fields[18].parse().unwrap();let p3:usize=fields[19].parse().unwrap();let(m1,m2,m3):(usize,usize,usize)=(fields[20].parse().unwrap(),fields[21].parse().unwrap(),fields[22].parse().unwrap());need(fields[23].parse::<usize>().unwrap()==4,"fast K14 terminal degree");
 let s14=sig(&row14,e);let ps1=valid(s14,e);need(ps1.len()==m1&&ps1.contains(&p1),"fast K14 p1/m1 mismatch");need(t1<e.tails[p1][first-2].len(),"fast K14 t1 range");let row1=replace(&row14,&e.anchors[p1],&e.tails[p1][first-2][t1]);need(row1==unhex(fields[25]),"fast K14 row1 mismatch");let s1=sig(&row1,e);let ps2=avail(s1,e);need(ps2.len()==m2&&ps2.contains(&p2),"fast K14 p2/m2 mismatch");need(t2<e.tails[p2][second-2].len(),"fast K14 t2 range");let row2=replace(&row1,&e.anchors[p2],&e.tails[p2][second-2][t2]);need(row2==unhex(fields[26]),"fast K14 row2 mismatch");let s2=sig(&row2,e);let ps3=avail(s2,e);need(ps3.len()==m3&&ps3.contains(&p3),"fast K14 p3/m3 mismatch");let product=m1*m2*m3;need(product>0&&U%product as i128==0,"fast K14 denominator outside U");let q=terminal_charge(&row2,s2,p3,e);need(q==fields[24].parse().unwrap(),"fast K14 terminal q mismatch");need((number_flag(q)==1)==(fields[27]=="1"),"fast K14 nonzero flag mismatch");let _unit=source*U/product as i128;
