fn support_slot_matches(slot:usize,index:u64)->bool{let f=File::open("computations/unaudited-codex-orbit0-k24-charge-production-referee-2026-08-24/k24_k16_r44_support_candidates.tsv").unwrap();for(line_no,line)in BufReader::new(f).lines().enumerate(){let line=line.unwrap();if line_no==0{continue}let q:Vec<_>=line.split('\t').collect();if q[0].parse::<usize>().unwrap()==slot{return q[2].parse::<u64>().unwrap()==index}}false}
