 need(fields.len()==18,"fast K16 R2-2-4 sample arity");let ordinal:usize=fields[0].parse().unwrap();let index=parse_u(fields[1]);need(index<24_097_095&&ordinal==((index*257/24_097_095).min(256))as usize,"fast K16 R2-2-4 bin mismatch");let(row,v)=k16_head(index);need(v==parse_i(fields[2]),"fast K16 R2-2-4 coefficient mismatch");need(row==unhex(fields[3]),"fast K16 R2-2-4 source row mismatch");let p1:usize=fields[6].parse().unwrap();let t1:usize=fields[7].parse().unwrap();let p2:usize=fields[8].parse().unwrap();let t2:usize=fields[9].parse().unwrap();let p3:usize=fields[10].parse().unwrap();let m1:usize=fields[11].parse().unwrap();let m2:usize=fields[12].parse().unwrap();let m3:usize=fields[13].parse().unwrap();need(fields[17].parse::<usize>().unwrap()==4,"fast K16 R2-2-4 final degree");let s1=sig(&row,e);let ps1=avail(s1,e);need(ps1.len()==m1&&ps1.contains(&p1),"fast K16 R2-2-4 p1/m1 mismatch");need(t1<12,"fast K16 R2-2-4 t1 range");let row18=replace(&row,&e.anchors[p1],&e.tails[p1][0][t1]);need(row18==unhex(fields[4]),"fast K16 R2-2-4 K18 row mismatch");let s2=sig(&row18,e);let ps2=avail(s2,e);need(ps2.len()==m2&&ps2.contains(&p2),"fast K16 R2-2-4 p2/m2 mismatch");need(t2<12,"fast K16 R2-2-4 t2 range");let row20=replace(&row18,&e.anchors[p2],&e.tails[p2][0][t2]);need(row20==unhex(fields[5]),"fast K16 R2-2-4 K20 row mismatch");let s3=sig(&row20,e);let ps3=avail(s3,e);need(ps3.len()==m3&&ps3.contains(&p3),"fast K16 R2-2-4 p3/m3 mismatch");let product=m1*m2*m3;need(product>0&&U%product as i128==0,"fast K16 R2-2-4 denominator outside U");let unit=-(U/product as i128);need(unit==parse_i(fields[15]),"fast K16 R2-2-4 unit/sign mismatch");let q=terminal_charge(&row20,s3,p3,e);need(q==fields[14].parse().unwrap(),"fast K16 R2-2-4 terminal q mismatch");need(v*unit*q as i128==parse_i(fields[16]),"fast K16 R2-2-4 contribution mismatch");need(q!=0,"fast K16 R2-2-4 witness is zero");
